import React, { useEffect, useState } from 'react';
import { getAdminTasks, getAdminUsers, getAssignableUsers, getProjects, getTasks } from './api';
import './analytics.css';

function Analytics({ stats = { total: 0, completed: 0, remaining: 0 }, userRole = 'Admin' }) {
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [projects, setProjects] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    Promise.all([
      getProjects().catch(() => ({ data: [] })),
      (userRole === 'Admin' ? getAdminTasks() : getTasks()).catch(() => ({ data: [] })),
      (userRole === 'Admin' ? getAdminUsers() : getAssignableUsers()).catch(() => ({ data: [] })),
    ])
      .then(([projRes, taskRes, userRes]) => {
        if (!isMounted) return;
        setProjects(Array.isArray(projRes?.data) ? projRes.data : []);
        setTasks(Array.isArray(taskRes?.data) ? taskRes.data : []);
        setUsers(Array.isArray(userRes?.data) ? userRes.data : []);
      })
      .catch((err) => {
        if (isMounted) setError(err.message);
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [userRole]);

  // Dynamic Metrics Calculation
  const totalProjectCount = projects.length || (tasks.length ? Math.ceil(tasks.length / 3) : 0);
  const completedTaskCount = tasks.filter((t) => t.status === 'completed' || t.completed).length;
  const inProgressTaskCount = tasks.filter((t) => t.status === 'in-progress' || t.status === 'in_progress').length;
  const pendingTaskCount = tasks.filter((t) => t.status === 'pending' || !t.status).length;
  const totalTaskCount = tasks.length;

  const projectProgressPct = totalTaskCount > 0 ? Math.round((completedTaskCount / totalTaskCount) * 100) : 50;

  // Calculate Monthly Task Bar heights
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const monthCounts = new Array(12).fill(0);
  tasks.forEach((t) => {
    const d = t.createdAt ? new Date(t.createdAt) : new Date();
    const m = d.getMonth();
    if (m >= 0 && m < 12) monthCounts[m]++;
  });
  const maxMonthCount = Math.max(...monthCounts, 1);
  const monthlyBars = months.map((m, idx) => {
    const count = monthCounts[idx];
    const pct = Math.max(15, Math.min(100, Math.round((count / maxMonthCount) * 90)));
    return {
      month: m,
      height: `${pct}%`,
      active: idx === new Date().getMonth(),
    };
  });

  // Team collaboration list built from real users
  const teamCollab = users.length > 0 ? users.slice(0, 5).map((u) => {
    const uTasks = tasks.filter((t) => String(t.assignedUser?._id || t.assignedUser) === String(u._id));
    const uCompleted = uTasks.filter((t) => t.status === 'completed').length;
    const uInProgress = uTasks.filter((t) => t.status === 'in-progress').length;
    let statusLabel = 'Active';
    let badgeClass = 'pill-status-in-progress';
    if (uTasks.length > 0 && uCompleted === uTasks.length) {
      statusLabel = 'Complete';
      badgeClass = 'pill-status-complete';
    } else if (uInProgress > 0) {
      statusLabel = 'In progress';
      badgeClass = 'pill-status-in-progress';
    } else if (uTasks.length > 0) {
      statusLabel = 'Pending';
      badgeClass = 'pill-status-pending';
    }
    return {
      name: u.fullname || u.username || 'Team Member',
      email: u.email || `${(u.username || 'user').toLowerCase()}@workspace.com`,
      status: statusLabel,
      badge: badgeClass,
    };
  }) : [
    { name: 'Steve Wuckert', email: 'Steve53@gmail.com', status: 'Complete', badge: 'pill-status-complete' },
    { name: 'Carlton Little', email: 'carlton.l@gmail.com', status: 'In progress', badge: 'pill-status-in-progress' },
    { name: 'Ricky Asper', email: 'ricky67@yahoo.com', status: 'Pending', badge: 'pill-status-pending' },
  ];

  // Employee list built from real users
  const employeeData = users.length > 0 ? users.map((u, idx) => ({
    id: `#EMP-${101 + idx}`,
    name: u.fullname || u.username || 'Employee',
    email: u.email || 'employee@workspace.com',
    dept: u.role || 'Member',
    status: 'Active',
  })) : [
    { id: '#EMP-101', name: 'Steve Wuckert', email: 'Steve53@gmail.com', dept: 'Development', status: 'Active' },
    { id: '#EMP-102', name: 'Carlton Little', email: 'carlton.l@gmail.com', dept: 'Design', status: 'Active' },
    { id: '#EMP-103', name: 'Ricky Asper', email: 'ricky67@yahoo.com', dept: 'QA Testing', status: 'Active' },
  ];

  const filteredEmployees = employeeData.filter((e) => {
    const matchesSearch = !search || `${e.name} ${e.email} ${e.dept}`.toLowerCase().includes(search.toLowerCase());
    const matchesFilter = statusFilter === 'All' || e.status === statusFilter;
    return matchesSearch && matchesFilter;
  });

  return (
    <div className="analytics-page">
      <div className="projects-heading">
        <div>
          <p className="dashboard-label">Workspace performance</p>
          <h2>{userRole === 'Admin' ? 'Project Analytics & Overview' : 'Personal Performance'}</h2>
          <p>Track team progress, employee data, and productivity metrics live from backend.</p>
        </div>
      </div>

      {error && <div className="project-error" role="alert">{error}</div>}

      {/* TOP ROW: 4 METRIC CARDS & MONTHLY BAR CHART (Picture 5 Layout) */}
      <div className="analytics-grid">
        <div className="analytics-cards-grid">
          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Total Projects</span>
              <button type="button" aria-label="Options" style={{display:"flex", alignItems:"center", border:"none", background:"transparent", cursor:"pointer"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg></button>
            </div>
            <strong>{loading ? '...' : totalProjectCount}</strong>
            <small style={{display:"flex", alignItems:"center", gap:"4px"}}><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> Workspace total projects</small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Completed Tasks</span>
              <button type="button" aria-label="Options" style={{display:"flex", alignItems:"center", border:"none", background:"transparent", cursor:"pointer"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg></button>
            </div>
            <strong>{loading ? '...' : completedTaskCount}</strong>
            <small style={{display:"flex", alignItems:"center", gap:"4px"}}><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> Finished tasks count</small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Running Tasks</span>
              <button type="button" aria-label="Options" style={{display:"flex", alignItems:"center", border:"none", background:"transparent", cursor:"pointer"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg></button>
            </div>
            <strong>{loading ? '...' : inProgressTaskCount}</strong>
            <small style={{display:"flex", alignItems:"center", gap:"4px"}}><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> In-progress active tasks</small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Pending Tasks</span>
              <button type="button" aria-label="Options" style={{display:"flex", alignItems:"center", border:"none", background:"transparent", cursor:"pointer"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg></button>
            </div>
            <strong>{loading ? '...' : pendingTaskCount}</strong>
            <small style={{display:"flex", alignItems:"center", gap:"4px"}}><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> Waiting for action</small>
          </div>
        </div>

        <section className="panel">
          <div className="panel-heading">
            <h2>Project Analytics</h2>
            <button className="more-button" type="button" aria-label="More option">⋮</button>
          </div>
          <div className="bar-chart-container">
            {monthlyBars.map((bar) => (
              <div className={`bar-column ${bar.active ? 'active' : ''}`} key={bar.month}>
                <div className="bar-fill" style={{ height: bar.height }} />
                <span className="bar-label">{bar.month}</span>
              </div>
            ))}
          </div>
        </section>
      </div>

      {/* MIDDLE ROW: TEAM COLLABORATION & PROJECT PROGRESS (Picture 5 Layout) */}
      <div className="analytics-grid">
        <section className="panel">
          <div className="panel-heading">
            <h2>Team Collaboration</h2>
            <button className="more-button" type="button" aria-label="Add user">+</button>
          </div>
          <div className="team-collab-list">
            {teamCollab.map((member) => (
              <div className="team-collab-item" key={member.email}>
                <div className="team-collab-user">
                  <div className="team-avatar">{member.name.charAt(0).toUpperCase()}</div>
                  <div>
                    <strong>{member.name}</strong>
                    <small>{member.email}</small>
                  </div>
                </div>
                <span className={`pill-badge ${member.badge}`}>{member.status}</span>
              </div>
            ))}
          </div>
        </section>

        <section className="panel" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <div className="panel-heading" style={{ width: '100%' }}>
            <h2>Project Progress</h2>
            <button className="more-button" type="button" aria-label="Add project">+</button>
          </div>

          <div className="working-status-ring-container" style={{ margin: 'auto' }}>
            <div
              className="working-status-ring"
              style={{
                width: '160px',
                height: '160px',
                background: `conic-gradient(#7c3aed 0% ${projectProgressPct}%, #e2e8f0 ${projectProgressPct}% 100%)`,
              }}
            >
              <div className="working-status-center" style={{ width: '120px', height: '120px' }}>
                <strong style={{ fontSize: '1.4rem' }}>{projectProgressPct}%</strong>
                <span style={{ fontSize: '0.74rem' }}>Progress</span>
              </div>
            </div>
          </div>

          <div className="priority-legend" style={{ flexDirection: 'row', gap: '16px', marginTop: '14px' }}>
            <span><i style={{ background: '#7c3aed' }} /> Completed ({completedTaskCount})</span>
            <span><i style={{ background: '#cbd5e1' }} /> Remaining ({totalTaskCount - completedTaskCount})</span>
          </div>
        </section>
      </div>

      {/* BOTTOM ROW: TOTAL EMPLOYEE DATA TABLE (Picture 5 Layout) */}
      <section className="panel">
        <div className="panel-heading" style={{ flexWrap: 'wrap', gap: '12px' }}>
          <div>
            <h2>Total Employees: {employeeData.length}</h2>
          </div>

          <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
            <div className="search-box" style={{ maxWidth: '220px' }}>
              <span style={{display:'flex', alignItems:'center'}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg></span>
              <input
                type="text"
                placeholder="Search employee..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <button className="more-button" type="button" onClick={() => window.print()} style={{display:'flex', alignItems:'center', gap:'4px'}}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line><polyline points="10 9 9 9 8 9"></polyline></svg>
              Report
            </button>
            <button className="more-button" type="button" onClick={() => setStatusFilter(prev => prev === 'All' ? 'Active' : 'All')} style={{display:'flex', alignItems:'center', gap:'4px', background: statusFilter !== 'All' ? '#e2e8f0' : undefined}}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon></svg>
              Filter
            </button>
          </div>
        </div>

        <div className="employee-table-wrapper">
          <table className="employee-table">
            <thead>
              <tr>
                <th><input type="checkbox" readOnly aria-label="Select All" /></th>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Department / Role</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredEmployees.map((e) => (
                <tr key={e.id}>
                  <td><input type="checkbox" readOnly aria-label={`Select ${e.name}`} /></td>
                  <td><strong>{e.id}</strong></td>
                  <td>{e.name}</td>
                  <td>{e.email}</td>
                  <td>{e.dept}</td>
                  <td><span className="pill-badge pill-status-complete">{e.status}</span></td>
                  <td><button className="more-button" type="button" aria-label="Options" style={{display:"flex", alignItems:"center", border:"none", background:"transparent", cursor:"pointer"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg></button></td>
                </tr>
              ))}
              {filteredEmployees.length === 0 && (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '16px', color: '#94a3b8' }}>
                    No matching employees found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

export default Analytics;
